The screen shows LeetCode 44: Wildcard Matching. Match the entire string: `?` matches one character, and `*` matches any sequence, including empty. This implementation uses dynamic programming and returns a boolean; call `solve(s, p)` directly.

```javascript
function solve(s, p) {
  const n = p.length;
  const dp = new Array(n + 1).fill(false);
  dp[0] = true;

  for (let j = 1; j <= n; j++) {
    dp[j] = dp[j - 1] && p[j - 1] === '*';
  }

  for (let i = 1; i <= s.length; i++) {
    let diagonal = dp[0];
    dp[0] = false;

    for (let j = 1; j <= n; j++) {
      const above = dp[j];
      if (p[j - 1] === '*') {
        dp[j] = dp[j - 1] || above;
      } else {
        dp[j] = diagonal &&
          (p[j - 1] === '?' || p[j - 1] === s[i - 1]);
      }
      diagonal = above;
    }
  }

  return dp[n];
}
```

Time: O((s.length + 1) × (p.length + 1)). Auxiliary space: O(p.length + 1).

