The screen shows LeetCode 493, Reverse Pairs: count pairs where i < j and nums[i] > 2 * nums[j]. Use merge sort to count qualifying pairs between sorted halves before merging them.

```javascript
function solve(nums) {
  const a = nums.slice();
  const temp = new Array(a.length);

  function sort(left, right) {
    if (right - left <= 1) return 0;
    const mid = left + Math.floor((right - left) / 2);
    let count = sort(left, mid) + sort(mid, right);

    let j = mid;
    for (let i = left; i < mid; i++) {
      while (j < right && a[i] > 2 * a[j]) j++;
      count += j - mid;
    }

    let i = left;
    j = mid;
    let k = left;
    while (i < mid && j < right) {
      if (a[i] <= a[j]) temp[k++] = a[i++];
      else temp[k++] = a[j++];
    }
    while (i < mid) temp[k++] = a[i++];
    while (j < right) temp[k++] = a[j++];
    for (k = left; k < right; k++) a[k] = temp[k];

    return count;
  }

  return sort(0, a.length);
}
```

Call solve(nums); it returns the count without modifying nums. Time: O(n log n). Space: O(n).

