The screen shows LeetCode 200, Number of Islands: count groups of string "1" cells connected horizontally or vertically. Use iterative flood fill to visit each island once; the displayed example returns 3. This implementation preserves the input grid.

```javascript
function solve(grid) {
  const rows = grid.length;
  if (rows === 0 || grid[0].length === 0) return 0;
  const cols = grid[0].length;
  const visited = new Uint8Array(rows * cols);
  const stack = [];
  let islands = 0;

  function visit(r, c) {
    if (r < 0 || r >= rows || c < 0 || c >= cols) return;
    const id = r * cols + c;
    if (visited[id] || grid[r][c] !== '1') return;
    visited[id] = 1;
    stack.push(id);
  }

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (grid[r][c] !== '1' || visited[r * cols + c]) continue;
      islands++;
      visit(r, c);
      while (stack.length > 0) {
        const id = stack.pop();
        const row = Math.floor(id / cols);
        const col = id % cols;
        visit(row - 1, col);
        visit(row + 1, col);
        visit(row, col - 1);
        visit(row, col + 1);
      }
    }
  }
  return islands;
}
```

Call `solve(grid)` with a rectangular array of string zeros and ones; it returns the island count. Time: O(rows × cols). Auxiliary space: O(rows × cols).

